package com.personal.meditation;
import static org.junit.Assert.*;import android.content.*;import android.webkit.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.ActivityController;import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class)@Config(sdk=28)public class MainActivityTest{
 @Test public void appIsIndependentOfflineAndUsesTheAudioDocumentPicker()throws Exception{ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup();try{MainActivity a=controller.get();assertEquals("com.personal.meditation",a.getPackageName());WebSettings web=a.webForTests().getSettings();assertTrue(web.getBlockNetworkLoads());assertFalse(web.getAllowFileAccess());assertFalse(web.getAllowContentAccess());android.content.pm.PackageInfo info=a.getPackageManager().getPackageInfo(a.getPackageName(),android.content.pm.PackageManager.GET_PERMISSIONS|android.content.pm.PackageManager.GET_SERVICES);assertEquals(1,info.services.length);for(String permission:info.requestedPermissions)assertNotEquals("android.permission.INTERNET",permission);MeditationService.busy=false;a.bridgeForTests().chooseSound("bell");Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();Intent picked=Shadows.shadowOf(a).getNextStartedActivityForResult().intent;assertEquals(Intent.ACTION_OPEN_DOCUMENT,picked.getAction());assertEquals("audio/*",picked.getType());assertTrue(picked.hasCategory(Intent.CATEGORY_OPENABLE));}finally{controller.pause().stop().destroy();}}
 @Test public void vibrationPreviewUsesSavedLengthAndRespectsSessionAndEnabledState()throws Exception{ActivityController<MainActivity> controller=Robolectric.buildActivity(MainActivity.class).setup();MainActivity a=controller.get();android.os.Vibrator vibrator=(android.os.Vibrator)a.getSystemService(Context.VIBRATOR_SERVICE);org.robolectric.shadows.ShadowVibrator shadow=Shadows.shadowOf(vibrator);shadow.setHasVibrator(true);Settings settings=new Settings(a);org.json.JSONObject config=settings.get();config.getJSONObject("vibrations").getJSONObject("quarter").put("enabled",true).put("ms",420);assertTrue(settings.save(config.toString()));MeditationService.busy=false;try{a.bridgeForTests().previewVibration("quarter");Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertTrue(shadow.isVibrating());assertEquals(420,shadow.getMilliseconds());a.bridgeForTests().stopPreview();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertFalse(shadow.isVibrating());MeditationService.busy=true;a.bridgeForTests().previewVibration("quarter");Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertFalse(shadow.isVibrating());MeditationService.busy=false;config.getJSONObject("vibrations").getJSONObject("quarter").put("enabled",false);assertTrue(settings.save(config.toString()));a.bridgeForTests().previewVibration("quarter");a.bridgeForTests().previewVibration("unknown");Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertFalse(shadow.isVibrating());config.getJSONObject("vibrations").getJSONObject("quarter").put("enabled",true);assertTrue(settings.save(config.toString()));a.bridgeForTests().previewVibration("quarter");Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();assertTrue(shadow.isVibrating());controller.pause();assertFalse(shadow.isVibrating());}finally{MeditationService.busy=false;controller.stop().destroy();}}

}
